import "./paragraph.css";
import { RichValue } from "@/registry/p1/internal/rich";

export interface ParagraphProps {
  text: unknown;
  style: "body" | "lead";
  size: "small" | "regular" | "large";
  align: "left" | "center";
}

export function Paragraph({ text, style, size, align }: ParagraphProps) {
  return (
    <div className="p1-paragraph p1-block" data-style={style} data-size={size} data-align={align}>
      <RichValue value={text} className="p1-paragraph__body" />
    </div>
  );
}

"use client";

import type { ComponentConfig } from "@puckeditor/core";
import { richtextField } from "@pantheon-systems/puck-css/fields";
import { defineMeta } from '../define-meta';
import { Paragraph, type ParagraphProps } from "./paragraph";
export type { ParagraphProps };

export const ParagraphBlock: ComponentConfig<ParagraphProps> = {
  fields: {
    text: richtextField,
    style: {
      type: "radio" as const,
      options: [
        { label: "Body", value: "body" },
        { label: "Lead", value: "lead" },
      ],
    },
    size: {
      type: "select" as const,
      options: [
        { label: "Small", value: "small" },
        { label: "Regular", value: "regular" },
        { label: "Large", value: "large" },
      ],
    },
    align: {
      type: "radio" as const,
      options: [
        { label: "Left", value: "left" },
        { label: "Center", value: "center" },
      ],
    },
  },
  defaultProps: {
    text: "This is a paragraph. Use it to expand on the heading above with a sentence or two of supporting detail — keep it clear, specific, and easy to scan.",
    style: "body",
    size: "regular",
    align: "left",
  },
  render: Paragraph,
};

export const meta = defineMeta({
  title: 'Paragraph',
  description: 'Rich-text paragraph in body or lead style with size and alignment controls; use for body copy blocks.',
  categories: ["content"],
  published: true,
  dependencies: ["@puckeditor/core","@pantheon-systems/puck-css"],
  registryDependencies: ["@p1/tokens","@p1/internal-rich"],
});

.p1-paragraph {
  padding-block: var(--p1-space-sm);
}

.p1-paragraph__body {
  max-inline-size: 65ch;
  text-wrap: pretty;
  line-height: var(--p1-leading-normal);
}

.p1-paragraph[data-align="center"] .p1-paragraph__body {
  margin-inline: auto;
  text-align: center;
}

.p1-paragraph[data-align="left"] .p1-paragraph__body {
  text-align: left;
}

/* Body style */
.p1-paragraph[data-style="body"] .p1-paragraph__body {
  color: var(--p1-fg-muted);
}

.p1-paragraph[data-style="body"][data-size="small"] .p1-paragraph__body {
  font-size: var(--p1-text-sm);
}

.p1-paragraph[data-style="body"][data-size="regular"] .p1-paragraph__body {
  font-size: var(--p1-text-base);
}

@media (width >= 48rem) {
  .p1-paragraph[data-style="body"][data-size="regular"] .p1-paragraph__body {
    font-size: var(--p1-text-lg);
  }
}

.p1-paragraph[data-style="body"][data-size="large"] .p1-paragraph__body {
  font-size: var(--p1-text-lg);
}

@media (width >= 48rem) {
  .p1-paragraph[data-style="body"][data-size="large"] .p1-paragraph__body {
    font-size: var(--p1-text-xl);
  }
}

/* Lead style */
.p1-paragraph[data-style="lead"] .p1-paragraph__body {
  font-family: Georgia, serif;
  font-size: var(--p1-text-xl);
  color: var(--p1-fg-default);
}

@media (width >= 48rem) {
  .p1-paragraph[data-style="lead"] .p1-paragraph__body {
    font-size: var(--p1-text-2xl);
  }
}

